bool hasPermission(int) { return true; }
void enforcePermission(int) {}
void logDenied(int) {}
void vendorCall(int) {}

void rollSurface(int uid)
{
  if (!hasPermission(uid)) {
    logDenied(uid);
    return;
  }
  enforcePermission(uid);
}

void rollSurfaceVariant(int uid)
{
  if (!hasPermission(uid)) {
    logDenied(uid);
    return;
  }
  enforcePermission(uid);
}

void rollSurfaceDecoy(int uid)
{
  vendorCall(uid);
}
